INSERT INTO restaurants (slug, name, category, website, description, brand_color) VALUES ('aw', 'A&W', 'restaurant', 'https://web.aw.ca/', 'Burgers, breakfast sandwiches, poutine and root beer', '#e36b0a') ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, website = EXCLUDED.website, description = EXCLUDED.description, brand_color = EXCLUDED.brand_color;
